@file:Suppress("MagicNumber", "SpreadOperator")

package dev.hfps.reveal.pipeline.cpu

/**
 * "Camera JPEG match" for the Sony ZV-E10, and the tone of Standard: fitted to the camera's own JPEGs
 * (docs/adr/0008, "Calibration"). Generated by `CameraMatchCalibrationTest` (opt-in, on copies of the owner's
 * RAW+JPEG pairs, never committed); only these parameters and the aggregate errors leave the machine.
 *
 * Model, from Reveal's scene-linear Rec.2020 (as-shot white balance, camera matrix, exposure 0) to the JPEG:
 * `rgb' = S2R * hue(curve(R2S * M * 2^GAIN_EV * rgb))`, where `M` is a 3x3 with rows summing to 1 (white stays
 * white), `R2S`/`S2R` convert between Rec.2020 and linear sRGB primaries (the camera applies its curve per channel
 * in its output space), `curve` the 16-knot [ToneCurve] and `hue` the order-3 [HueTreatment].
 */
object CameraMatchZvE10 {
    // ---- Camera JPEG match (free 16-knot curve + matrix + hue treatment) ----

    /** Profile gain (baseline exposure) in EV. */
    const val GAIN_EV: Double = 1.64467

    /** `M`, row-major, rows sum to 1. */
    val MATRIX: DoubleArray = doubleArrayOf(
        1.33774, -0.506418, 0.168674,
        -0.237985, 1.21731, 0.0206748,
        0.0915767, -0.362695, 1.27112,
    )

    /** Knot values of the curve (display-linear at `2^-10 .. 2^5`). */
    val CURVE: DoubleArray = doubleArrayOf(
        0.000302144, 0.000662313, 0.00145294, 0.00305439, 0.00691114, 0.0164621, 0.0392255, 0.0897577,
        0.201047, 0.438411, 0.823284, 0.975014, 0.997009, 0.999646, 0.999958, 0.999995,
    )

    /** Hue treatment: chroma gain coefficients. */
    val HUE_CHROMA: DoubleArray = doubleArrayOf(
        -0.157402,
        0.00647486,
        -0.0372118,
        -0.0102672,
        -0.0335107,
        -0.0483217,
        -0.00250350,
    )

    /** Hue treatment: hue rotation coefficients (radians). */
    val HUE_SHIFT: DoubleArray = doubleArrayOf(
        -0.0134177,
        0.0754380,
        -0.0454516,
        -0.0845482,
        -0.0160582,
        0.0104920,
        0.0367171,
    )

    // ---- Standard's tone ([ProfileLooks.Filmic] fitted with a free matrix; Standard keeps only the tone) ----

    /** Fitted: Standard's baseline exposure. */
    const val STANDARD_GAIN_EV: Double = 1.31314

    /** Fitted: slope at grey, stops per stop. */
    const val STANDARD_CONTRAST: Double = 1.13388

    /** Fitted: shadow toe. */
    const val STANDARD_TOE: Double = 0.0782667

    /**
     * Designed, not fitted: the JPEG patches stop below level 250, so the fit cannot see the top of the curve (it
     * found a hard shoulder, n = 7.56, towards 0.958). Standard approaches display white 1.0 instead (A = log2(1/0.18))
     * with a softer shoulder (n = 5), which puts the sensor clip at about 0.98 and keeps the RAW's last stop of
     * highlights separable instead of flattening it at the camera's clip.
     */
    const val STANDARD_SHOULDER: Double = 5.0

    /** Designed: `log2(1 / 0.18)`, the curve's asymptote is display white. */
    val STANDARD_WHITE_STOPS: Double = StrictMath.log(1.0 / 0.18) / StrictMath.log(2.0)

    /** Linear Rec.2020 to linear sRGB primaries. */
    val R2S: Mat3 = ColorSpaces.SRGB.fromXyz * ColorSpaces.REC2020.toXyz

    /** The look at 100 %. */
    fun look(): ProfileLooks.Look = look(GAIN_EV, MATRIX, CURVE, HUE_CHROMA, HUE_SHIFT)

    /** The look for a set of fitted parameters (the calibration validates its fit through this). */
    fun look(
        gainEv: Double,
        matrix: DoubleArray,
        curve: DoubleArray,
        hueChroma: DoubleArray,
        hueShift: DoubleArray,
    ): ProfileLooks.Look {
        val gain = StrictMath.pow(2.0, gainEv)
        return ProfileLooks.Look(
            pre = R2S * Mat3(*matrix) * Mat3.diagonal(gain, gain, gain),
            curve = ToneCurve.monotone(curve),
            post = R2S.inverse(),
            hueChroma = hueChroma,
            hueShift = hueShift,
        )
    }
}
